import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import {
  HEARTBEAT_STALE_MS,
  IDEMPOTENCY_KEY_RE,
  nowIso,
  toJob,
  validateNewJob,
  type FieldError,
  type JobRow,
  type NewJob,
} from './jobs.ts';

const MAX_BODY_BYTES = 16 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const stmts = {
  getJob: db.prepare('SELECT * FROM jobs WHERE id = ?'),
  listJobs: db.prepare('SELECT * FROM jobs ORDER BY rowid DESC'),
  insertJob: db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, result_output, error, run_after, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, 0, ?, ?)`,
  ),
  getKey: db.prepare('SELECT fingerprint, job_id FROM idempotency_keys WHERE key = ?'),
  insertKey: db.prepare('INSERT INTO idempotency_keys (key, fingerprint, job_id) VALUES (?, ?, ?)'),
  workerHeartbeat: db.prepare("SELECT seen_at FROM heartbeats WHERE name = 'worker'"),
};

function getRow(id: string): JobRow | undefined {
  return stmts.getJob.get(id) as unknown as JobRow | undefined;
}

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  sendJson(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

function notAllowed(res: ServerResponse, allow: string): void {
  sendJson(res, 405, { error: { code: 'method_not_allowed', message: `Method not allowed. Allowed: ${allow}.` } }, { allow });
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function isJsonContentType(value: string | undefined): boolean {
  return value !== undefined && value.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

type SubmitResult = { kind: 'created' | 'replayed'; row: JobRow } | { kind: 'conflict' };

/**
 * Inserts a job, or resolves an idempotency key. The check and the insert run in one
 * IMMEDIATE transaction so a key can never create two jobs.
 */
function submit(job: NewJob, key: string | undefined): SubmitResult {
  const fingerprint = JSON.stringify([job.input, job.steps, job.failAttempts]);
  let result: SubmitResult;
  db.exec('BEGIN IMMEDIATE');
  let committed = false;
  try {
    const existing =
      key === undefined ? undefined : (stmts.getKey.get(key) as unknown as { fingerprint: string; job_id: string } | undefined);
    if (existing) {
      result =
        existing.fingerprint === fingerprint
          ? { kind: 'replayed', row: getRow(existing.job_id)! }
          : { kind: 'conflict' };
    } else {
      const id = randomUUID();
      const now = nowIso();
      stmts.insertJob.run(id, job.input, job.steps, job.failAttempts, now, now);
      if (key !== undefined) stmts.insertKey.run(key, fingerprint, id);
      result = { kind: 'created', row: getRow(id)! };
    }
    db.exec('COMMIT');
    committed = true;
  } finally {
    if (!committed) db.exec('ROLLBACK');
  }
  return result;
}

async function createJobRoute(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];
  const keyHeader = req.headers['idempotency-key'];
  const key = keyHeader === undefined ? undefined : String(keyHeader);
  if (key !== undefined && !IDEMPOTENCY_KEY_RE.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must be 1 to 128 characters: letters, digits, "_" or "-".' });
  }

  const { text, tooLarge } = await readBody(req);
  let parsed: unknown;
  if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else if (tooLarge) {
    fields.push({ field: 'body', message: `Request body must be at most ${MAX_BODY_BYTES} bytes.` });
  } else {
    try {
      parsed = JSON.parse(text);
    } catch {
      fields.push({ field: 'body', message: 'Malformed JSON.' });
    }
  }
  if (fields.length > 0) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
    return;
  }

  const validated = validateNewJob(parsed);
  if (!validated.ok) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', validated.fields);
    return;
  }

  const outcome = submit(validated.job, key);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, toJob(outcome.row));
}

function health(res: ServerResponse): void {
  const heartbeat = stmts.workerHeartbeat.get() as unknown as { seen_at: number } | undefined;
  const up = heartbeat !== undefined && Date.now() - heartbeat.seen_at <= HEARTBEAT_STALE_MS;
  sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const path = new URL(req.url ?? '/', 'http://localhost').pathname;
  const method = req.method ?? '';

  if (path === '/') {
    if (method !== 'GET') return notAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (path === '/health') {
    if (method !== 'GET') return notAllowed(res, 'GET');
    return health(res);
  }
  if (path === '/api/jobs') {
    if (method === 'GET') {
      sendJson(res, 200, { jobs: (stmts.listJobs.all() as unknown as JobRow[]).map(toJob) });
      return;
    }
    if (method === 'POST') return createJobRoute(req, res);
    return notAllowed(res, 'GET, POST');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (match) {
    if (method !== 'GET') return notAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No job with that id.');
    }
    const row = getRow(id);
    if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
    sendJson(res, 200, toJob(row));
    return;
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((error: unknown) => {
    console.error('request failed:', error);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});
server.listen(port, () => console.log(`server listening on port ${port}`));

let stopping = false;
function shutdown(): void {
  if (stopping) return;
  stopping = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

