/** Job model, constants, and request validation shared by the server and the worker. */

export const MAX_ATTEMPTS = 3;
/** Duration of one processing step. */
export const STEP_MS = 100;
/** Delay before a failed attempt is retried (must be between 250 ms and 2 s). */
export const RETRY_DELAY_MS = 500;
/** How often the worker writes its heartbeat. */
export const HEARTBEAT_MS = 1000;
/** The worker counts as "up" if its last heartbeat is no older than this. */
export const HEARTBEAT_STALE_MS = 3000;
export const TRANSIENT_ERROR = 'transient failure';
export const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table. */
export interface JobRow {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  run_after: number;
  created_at: string;
  updated_at: string;
}

/** The JSON shape returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export function nowIso(): string {
  return new Date().toISOString();
}

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);

function checkInteger(body: Record<string, unknown>, name: string, min: number, max: number, fallback: number, fields: FieldError[]): number {
  if (!Object.hasOwn(body, name)) return fallback;
  const value = body[name];
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    fields.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
    return fallback;
  }
  return value;
}

/** Validates a parsed POST /api/jobs body. Returns every problem found, not just the first. */
export function validateNewJob(body: unknown): { ok: true; job: NewJob } | { ok: false; fields: FieldError[] } {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'Request body must be a JSON object.' }] };
  }
  const record = body as Record<string, unknown>;
  const fields: FieldError[] = [];
  for (const key of Object.keys(record)) {
    if (!KNOWN_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  let input = '';
  const raw = record.input;
  if (!Object.hasOwn(record, 'input')) {
    fields.push({ field: 'input', message: 'Required.' });
  } else if (typeof raw !== 'string') {
    fields.push({ field: 'input', message: 'Must be a string.' });
  } else if (raw.length < 1 || raw.length > 1000) {
    fields.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
  } else if (raw.trim() === '') {
    fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  } else {
    input = raw;
  }

  const steps = checkInteger(record, 'steps', 1, 20, 5, fields);
  const failAttempts = checkInteger(record, 'failAttempts', 0, 5, 0, fields);
  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, job: { input, steps, failAttempts } };
}

