22	<body>
23	  <h1>Job tracker</h1>
24	
25	  <form data-testid="job-form" id="job-form">
26	    <label>Input
27	      <input data-testid="job-input" name="input" type="text" autocomplete="off">
28	    </label>
29	    <label>Steps
