34	    </label>
35	    <button data-testid="job-submit" type="submit">Submit</button>
36	  </form>
37	
38	  <div data-testid="form-error" role="alert" id="form-error"></div>
39	
40	  <ul data-testid="job-list" id="job-list"></ul>
41	
42	  <script>
43	    const form = document.getElementById('job-form');
44	    const submitButton = form.querySelector('[data-testid="job-submit"]');
45	    const errorBox = document.getElementById('form-error');
46	    const list = document.getElementById('job-list');
47	
48	    // Numeric-looking values are sent as numbers; anything else is sent as typed so the API rejects it.
49	    function numericOrRaw(value) {
50	      const trimmed = value.trim();
51	      return /^[-+]?\d+(\.\d+)?$/.test(trimmed) ? Number(trimmed) : value;
52	    }
53	
54	    function describeRejection(body, status) {
55	      const error = body && body.error;
56	      if (!error) return 'Request failed with status ' + status + '.';
57	      const lines = [error.message || 'The request was rejected.'];
58	      for (const f of error.fields || []) lines.push(f.field + ': ' + f.message);
59	      return lines.join('\n');
60	    }
61	
62	    form.addEventListener('submit', async (event) => {
63	      event.preventDefault();
64	      errorBox.textContent = '';
65	      const data = new FormData(form);
66	      const body = {
67	        input: data.get('input'),
68	        steps: numericOrRaw(data.get('steps')),
69	        failAttempts: numericOrRaw(data.get('failAttempts')),
70	      };
71	      submitButton.disabled = true;
72	      try {
73	        const res = await fetch('/api/jobs', {
74	          method: 'POST',
75	          headers: { 'content-type': 'application/json' },
76	          body: JSON.stringify(body),
77	        });
78	        const json = await res.json().catch(() => null);
79	        if (!res.ok) {
80	          errorBox.textContent = describeRejection(json, res.status);
81	          return;
82	        }
83	        form.elements.input.value = '';
84	        await refresh();
85	      } catch (e) {
86	        errorBox.textContent = 'Could not reach the server.';
87	      } finally {
88	        submitButton.disabled = false;
89	      }
90	    });
91	
92	    function renderJob(job) {
93	      const li = document.createElement('li');
94	      li.dataset.testid = 'job-item';
95	      li.dataset.jobId = job.id;
96	
97	      const status = document.createElement('span');
98	      status.dataset.testid = 'job-status';
99	      status.className = 'status-' + job.status;
100	      status.textContent = job.status;
101	
102	      const progress = document.createElement('span');
103	      progress.dataset.testid = 'job-progress';
104	      progress.textContent = job.progress.completed + '/' + job.progress.total;
105	
106	      const result = document.createElement('span');
107	      result.dataset.testid = 'job-result';
108	      if (job.status === 'completed' && job.result) result.textContent = job.result.output;
109	      else if (job.status === 'failed') result.textContent = job.error || '';
110	      else result.textContent = '';
111	
112	      const input = document.createElement('span');
113	      input.className = 'input';
114	      input.textContent = 'Input: ' + job.input + ' (attempts: ' + job.attempts + ')';
115	
116	      li.append(status, progress, result, input);
117	      return li;
118	    }
119	
120	    async function refresh() {
121	      try {
122	        const res = await fetch('/api/jobs', { cache: 'no-store' });
123	        if (!res.ok) return;
124	        const { jobs } = await res.json();
125	        list.replaceChildren(...jobs.map(renderJob));
